from collections import defaultdict

def parse_nested_json(data, key):
    if not isinstance(data, dict):
        return None
    if key in data:
        return data[key]
    for k, v in data.items():
        result = parse_nested_json(v, key)
        if result is not None:
            return result
    return None

def safe_parse_json(json_data, key_path):
    def _parse_nested_json(data):
        return parse_nested_json(data, key_path[0])
    if not isinstance(json_data, dict):
        return None
    if key_path[0] not in json_data:
        return None
    if len(key_path) == 1:
        return _parse_nested_json(json_data[key_path[0]])
    else:
        return safe_parse_json(json_data[key_path[0]], key_path[1:])

# Example usage:
json_data = {
    "a": {
        "b": {
            "c": "value"
        }
    }
}

key_path = ["a", "b", "c"]

print(safe_parse_json(json_data, key_path))  # Output: "value"
